import{az as a,P as d,Q as e,aQ as s}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"server/base/index.md","filePath":"server/base/index.md","lastUpdated":1785339991000}'),n={name:"server/base/index.md"};function l(r,t,i,p,o,c){return d(),e("div",null,[...t[0]||(t[0]=[s(`<h2 id="网络基础概述" tabindex="-1">网络基础概述 <a class="header-anchor" href="#网络基础概述" aria-label="Permalink to “网络基础概述”">​</a></h2><p><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/Overview" target="_blank" rel="noreferrer">MDN HTTP 概述</a></p><p>计算机网络是现代 Web 应用的基石。从浏览器输入 URL 到页面渲染完成，背后涉及多层协议的协作。理解网络协议体系，有助于排查通信问题与优化性能。</p><h2 id="osi-七层模型" tabindex="-1">OSI 七层模型 <a class="header-anchor" href="#osi-七层模型" aria-label="Permalink to “OSI 七层模型”">​</a></h2><p>OSI（Open Systems Interconnection）模型将网络通信划分为七个抽象层次，每层负责特定功能。</p><table tabindex="0"><thead><tr><th>层级</th><th>名称</th><th>主要协议</th><th>功能</th></tr></thead><tbody><tr><td>7</td><td>应用层</td><td>HTTP、DNS、SMTP</td><td>为应用提供网络服务</td></tr><tr><td>6</td><td>表示层</td><td>SSL/TLS、JPEG</td><td>数据格式转换与加密</td></tr><tr><td>5</td><td>会话层</td><td>NetBIOS、RPC</td><td>管理通信会话</td></tr><tr><td>4</td><td>传输层</td><td>TCP、UDP</td><td>端到端数据传输</td></tr><tr><td>3</td><td>网络层</td><td>IP、ICMP</td><td>路由与寻址</td></tr><tr><td>2</td><td>数据链路层</td><td>Ethernet、PPP</td><td>相邻节点间帧传输</td></tr><tr><td>1</td><td>物理层</td><td>光纤、网线</td><td>比特流传输</td></tr></tbody></table><h2 id="tcp-ip-四层模型" tabindex="-1">TCP/IP 四层模型 <a class="header-anchor" href="#tcp-ip-四层模型" aria-label="Permalink to “TCP/IP 四层模型”">​</a></h2><p>实际应用中更常使用 TCP/IP 四层模型，它是 OSI 模型的简化与实现。</p><table tabindex="0"><thead><tr><th>TCP/IP 层</th><th>对应 OSI 层</th><th>常见协议</th></tr></thead><tbody><tr><td>应用层</td><td>7、6、5</td><td>HTTP、HTTPS、WebSocket、DNS</td></tr><tr><td>传输层</td><td>4</td><td>TCP、UDP</td></tr><tr><td>网络层</td><td>3</td><td>IP、ICMP</td></tr><tr><td>网络接口层</td><td>2、1</td><td>Ethernet、Wi-Fi</td></tr></tbody></table><h2 id="核心协议简介" tabindex="-1">核心协议简介 <a class="header-anchor" href="#核心协议简介" aria-label="Permalink to “核心协议简介”">​</a></h2><h3 id="http-https" tabindex="-1">HTTP/HTTPS <a class="header-anchor" href="#http-https" aria-label="Permalink to “HTTP/HTTPS”">​</a></h3><p>Web 通信的基础协议，基于请求-响应模型。HTTPS 在 HTTP 之下加入 TLS 加密层，保证数据传输安全。</p><h3 id="tcp-udp" tabindex="-1">TCP/UDP <a class="header-anchor" href="#tcp-udp" aria-label="Permalink to “TCP/UDP”">​</a></h3><p>传输层两大协议。TCP 面向连接、可靠传输；UDP 无连接、高效但不可靠。</p><h3 id="websocket" tabindex="-1">WebSocket <a class="header-anchor" href="#websocket" aria-label="Permalink to “WebSocket”">​</a></h3><p>在单个 TCP 连接上实现全双工通信，适用于实时场景如聊天、推送。</p><h3 id="dns" tabindex="-1">DNS <a class="header-anchor" href="#dns" aria-label="Permalink to “DNS”">​</a></h3><p>域名系统，将人类可读的域名解析为 IP 地址，是互联网的&quot;电话簿&quot;。</p><h2 id="一次完整请求的流程" tabindex="-1">一次完整请求的流程 <a class="header-anchor" href="#一次完整请求的流程" aria-label="Permalink to “一次完整请求的流程”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 浏览器访问 https://example.com 的完整流程</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 1. DNS 解析：域名 -&gt; IP</span></span>
<span class="line"><span style="color:#FFCB6B;">dig</span><span style="color:#C3E88D;"> example.com</span><span style="color:#676E95;font-style:italic;">  # 返回 93.184.216.34</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 2. TCP 三次握手：建立连接</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 客户端 -&gt; SYN -&gt; 服务器</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 服务器 -&gt; SYN+ACK -&gt; 客户端</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 客户端 -&gt; ACK -&gt; 服务器</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 3. TLS 握手：协商加密参数（HTTPS）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 4. 发送 HTTP 请求</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 5. 服务器返回 HTTP 响应</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 6. 浏览器解析渲染</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 7. TCP 四次挥手：断开连接</span></span></code></pre></div><h2 id="协议对比总结" tabindex="-1">协议对比总结 <a class="header-anchor" href="#协议对比总结" aria-label="Permalink to “协议对比总结”">​</a></h2><table tabindex="0"><thead><tr><th>协议</th><th>所在层级</th><th>传输方式</th><th>可靠性</th><th>典型场景</th></tr></thead><tbody><tr><td>HTTP</td><td>应用层</td><td>请求-响应</td><td>依赖 TCP</td><td>网页、API</td></tr><tr><td>HTTPS</td><td>应用层</td><td>请求-响应</td><td>加密 + TCP</td><td>安全通信</td></tr><tr><td>TCP</td><td>传输层</td><td>字节流</td><td>可靠</td><td>文件传输</td></tr><tr><td>UDP</td><td>传输层</td><td>数据报</td><td>不可靠</td><td>视频直播</td></tr><tr><td>WebSocket</td><td>应用层</td><td>全双工</td><td>依赖 TCP</td><td>实时通信</td></tr><tr><td>DNS</td><td>应用层</td><td>UDP 为主</td><td>不可靠</td><td>域名解析</td></tr></tbody></table><p>网络协议是分层的，每一层只关注本层的职责，通过接口与上下层协作。掌握各层协议的特点与协作方式，是排查网络问题与优化性能的基础。</p>`,23)])])}const b=a(n,[["render",l]]);export{T as __pageData,b as default};
